create function pg_temp.ds_assert(ok boolean) returns void language plpgsql as $$begin if ok is not true then raise exception 'dashboard search assertion';end if;end$$;
create function pg_temp.ds_denied(q text,c text) returns void language plpgsql as $$declare actual text;begin begin execute q;exception when others then get stacked diagnostics actual=returned_sqlstate;end;if actual is distinct from c then raise exception 'expected %, got %',c,actual;end if;end$$;
